-- Create "auth_account_key" table
CREATE TABLE "public"."auth_account_key" (
  "id" smallint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "coin" character varying(10) NOT NULL,
  "key_type" character varying(20) NOT NULL DEFAULT 'bip44',
  "auth_account" character varying(20) NOT NULL,
  "account" character varying(20) NOT NULL DEFAULT 'deposit',
  "p2pkh_address" character varying(255) NOT NULL,
  "p2sh_segwit_address" character varying(255) NULL,
  "bech32_address" character varying(255) NULL,
  "taproot_address" character varying(255) NULL,
  "full_public_key" character varying(255) NOT NULL,
  "multisig_address" character varying(255) NOT NULL DEFAULT '',
  "redeem_script" character varying(255) NOT NULL DEFAULT '',
  "wallet_import_format" character varying(255) NOT NULL,
  "account_extended_privkey" character varying(255) NULL,
  "idx" bigint NOT NULL,
  "addr_status" smallint NOT NULL DEFAULT 0,
  "updated_at" timestamptz NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "chk_auth_account_key_coin" CHECK ((coin)::text = ANY ((ARRAY['btc'::character varying, 'bch'::character varying])::text[]))
);
-- Create index "idex_coin_auth_account_account" to table: "auth_account_key"
CREATE UNIQUE INDEX "idex_coin_auth_account_account" ON "public"."auth_account_key" ("coin", "auth_account", "account");
-- Create index "idx_auth_account" to table: "auth_account_key"
CREATE INDEX "idx_auth_account" ON "public"."auth_account_key" ("auth_account");
-- Create index "idx_auth_account_key_coin" to table: "auth_account_key"
CREATE INDEX "idx_auth_account_key_coin" ON "public"."auth_account_key" ("coin");
-- Create index "idx_auth_account_key_key_type" to table: "auth_account_key"
CREATE INDEX "idx_auth_account_key_key_type" ON "public"."auth_account_key" ("key_type");
-- Create index "idx_bech32_address" to table: "auth_account_key"
CREATE UNIQUE INDEX "idx_bech32_address" ON "public"."auth_account_key" ("bech32_address");
-- Create index "idx_p2pkh_address" to table: "auth_account_key"
CREATE UNIQUE INDEX "idx_p2pkh_address" ON "public"."auth_account_key" ("p2pkh_address");
-- Create index "idx_p2sh_segwit_address" to table: "auth_account_key"
CREATE UNIQUE INDEX "idx_p2sh_segwit_address" ON "public"."auth_account_key" ("p2sh_segwit_address");
-- Create index "idx_wallet_import_format" to table: "auth_account_key"
CREATE UNIQUE INDEX "idx_wallet_import_format" ON "public"."auth_account_key" ("wallet_import_format");
-- Set comment to table: "auth_account_key"
COMMENT ON TABLE "public"."auth_account_key" IS 'table for keys for auth account';
-- Set comment to column: "id" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."id" IS 'ID';
-- Set comment to column: "coin" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."coin" IS 'coin type code';
-- Set comment to column: "key_type" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."key_type" IS 'key type (bip44, bip49, bip84, bip86, musig2)';
-- Set comment to column: "auth_account" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."auth_account" IS 'auth type';
-- Set comment to column: "account" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."account" IS 'multisig account type (deposit, payment, stored)';
-- Set comment to column: "p2pkh_address" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."p2pkh_address" IS 'address as standard pubkey script that Pays To PubKey Hash (P2PKH)';
-- Set comment to column: "p2sh_segwit_address" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."p2sh_segwit_address" IS 'p2sh-segwit address';
-- Set comment to column: "bech32_address" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."bech32_address" IS 'bech32 address';
-- Set comment to column: "taproot_address" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."taproot_address" IS 'taproot address (BIP86)';
-- Set comment to column: "full_public_key" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."full_public_key" IS 'full public key';
-- Set comment to column: "multisig_address" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."multisig_address" IS 'multisig address';
-- Set comment to column: "redeem_script" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."redeem_script" IS 'redeedScript after multisig address generated';
-- Set comment to column: "wallet_import_format" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."wallet_import_format" IS 'WIF';
-- Set comment to column: "account_extended_privkey" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."account_extended_privkey" IS 'Account-level extended private key (xpriv) for BIP32 derivation';
-- Set comment to column: "idx" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."idx" IS 'index for hd wallet';
-- Set comment to column: "addr_status" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."addr_status" IS 'progress status for address generating';
-- Set comment to column: "updated_at" on table: "auth_account_key"
COMMENT ON COLUMN "public"."auth_account_key"."updated_at" IS 'updated date';
-- Create "musig2_nonces" table
CREATE TABLE "public"."musig2_nonces" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "signer_id" character varying(255) NOT NULL,
  "transaction_id" character varying(255) NOT NULL,
  "public_nonce" bytea NOT NULL,
  "is_used" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz NULL DEFAULT now(),
  "used_at" timestamptz NULL,
  PRIMARY KEY ("id")
);
-- Create index "idx_created_at" to table: "musig2_nonces"
CREATE INDEX "idx_created_at" ON "public"."musig2_nonces" ("created_at");
-- Create index "idx_is_used" to table: "musig2_nonces"
CREATE INDEX "idx_is_used" ON "public"."musig2_nonces" ("is_used");
-- Create index "idx_signer_transaction" to table: "musig2_nonces"
CREATE UNIQUE INDEX "idx_signer_transaction" ON "public"."musig2_nonces" ("signer_id", "transaction_id");
-- Create index "idx_transaction_id" to table: "musig2_nonces"
CREATE INDEX "idx_transaction_id" ON "public"."musig2_nonces" ("transaction_id");
-- Set comment to table: "musig2_nonces"
COMMENT ON TABLE "public"."musig2_nonces" IS 'MuSig2 nonce commitments for secure storage';
-- Set comment to column: "id" on table: "musig2_nonces"
COMMENT ON COLUMN "public"."musig2_nonces"."id" IS 'ID';
-- Set comment to column: "signer_id" on table: "musig2_nonces"
COMMENT ON COLUMN "public"."musig2_nonces"."signer_id" IS 'Signer identifier';
-- Set comment to column: "transaction_id" on table: "musig2_nonces"
COMMENT ON COLUMN "public"."musig2_nonces"."transaction_id" IS 'Transaction identifier';
-- Set comment to column: "public_nonce" on table: "musig2_nonces"
COMMENT ON COLUMN "public"."musig2_nonces"."public_nonce" IS 'Public nonce (66 bytes: two 33-byte compressed EC points R1||R2)';
-- Set comment to column: "is_used" on table: "musig2_nonces"
COMMENT ON COLUMN "public"."musig2_nonces"."is_used" IS 'true: nonce has been used in signing';
-- Set comment to column: "created_at" on table: "musig2_nonces"
COMMENT ON COLUMN "public"."musig2_nonces"."created_at" IS 'creation date';
-- Set comment to column: "used_at" on table: "musig2_nonces"
COMMENT ON COLUMN "public"."musig2_nonces"."used_at" IS 'date when nonce was marked as used';
-- Set comment to index: "idx_signer_transaction" on table: "musig2_nonces"
COMMENT ON INDEX "public"."idx_signer_transaction" IS 'Prevent duplicate nonces per signer-tx pair (CRITICAL for security)';
-- Create "seed" table
CREATE TABLE "public"."seed" (
  "id" smallint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "coin" character varying(10) NOT NULL,
  "seed" character varying(255) NOT NULL,
  "updated_at" timestamptz NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "chk_seed_coin" CHECK ((coin)::text = ANY ((ARRAY['btc'::character varying, 'bch'::character varying])::text[]))
);
-- Create index "idx_seed_coin" to table: "seed"
CREATE INDEX "idx_seed_coin" ON "public"."seed" ("coin");
-- Set comment to table: "seed"
COMMENT ON TABLE "public"."seed" IS 'table for seed';
-- Set comment to column: "id" on table: "seed"
COMMENT ON COLUMN "public"."seed"."id" IS 'ID';
-- Set comment to column: "coin" on table: "seed"
COMMENT ON COLUMN "public"."seed"."coin" IS 'coin type code';
-- Set comment to column: "seed" on table: "seed"
COMMENT ON COLUMN "public"."seed"."seed" IS 'seed';
-- Set comment to column: "updated_at" on table: "seed"
COMMENT ON COLUMN "public"."seed"."updated_at" IS 'updated date';
